import type { Argv, ArgumentsCamelCase, CommandModule } from 'yargs'
import { validateWorkingDir } from '../../util'
import { cwd } from 'process'
import { logger } from '../../logger'
import * as fs from 'fs'
import { createTelemetryClient } from '../../telemetry'
import { Project, Orchestrator } from '@servicenow/sdk-api'
import { type Telemetry, NowConfig } from '@servicenow/sdk-build-core'
import { credentialProvider } from '../../auth'

interface Arguments {
    ids: string[]
    source: string
    auth?: string | undefined
}

export const moveToApp: CommandModule<unknown, Arguments> = {
    command: 'move',
    describe: 'Move a file from a different application on the instance into this application',
    builder: (yargs: Argv) => {
        return yargs
            .option('ids', {
                describe: `Array of sys_ids of records to move into this app`,
                type: 'array',
                demandOption: true,
                string: true,
            })
            .option('source', {
                describe: `Path to the directory that contains package.json configuration`,
                default: cwd(),
                type: 'string',
            })
            .option('auth', {
                describe: 'Credential alias to use for authentication with instance',
                type: 'string',
                alias: 'a',
            })
            .check((args: Arguments) => demandNotEmpty(args, ['ids']))
            .example([['$0 move --ids id1 id2 id3', 'Contacts instance to claim records id1, id2, and id3']])
    },
    handler: async (args: ArgumentsCamelCase<Arguments>): Promise<void> => {
        let telemetryClient: Telemetry | undefined
        try {
            const credential = await credentialProvider(args.auth)
            telemetryClient = createTelemetryClient(fs, __dirname, credential.getUrl())

            logger.info('Customizing file(s)...')
            const workingDir = validateWorkingDir(args.source)
            const config = NowConfig.parseFromDirectory(workingDir, fs, logger)

            const project = new Project({ config, fileSystem: fs, rootDir: workingDir, logger, telemetryClient })

            const orchestrator = new Orchestrator(project, credential)

            await orchestrator.moveToApp({ sysIds: args.ids })
        } catch (error) {
            logger.error(error)

            process.exitCode = 1
        }
    },
}

function demandNotEmpty(args: Arguments, demandedOptions: (keyof Arguments)[]): boolean {
    for (const option of demandedOptions) {
        if (args[option] === '') {
            throw new Error(`Missing required argument for --${option}`)
        }
    }
    return true
}
